/bin/bash -c "python3 - <<'PY'
import cv2, numpy as np
im=cv2.imread('first_frame.png').astype(float)
# print rows of green/cyan edges along box
for y in range(47,88):
 vals=[]
 for x in range(103,154):
  b,g,r=im[y,x]
  if g-r>5 or g-b>5 or b-r>5: vals.append(x)
 if vals: print(y, min(vals),max(vals),len(vals))
